INSERT INTO `recipes` VALUES
(1,'019be31d-6b0c-7311-8dc9-3ca07c762f90',1,'019be31f-29ec-7108-85f5-613d49a6b099','Butter Croissant','PT-BUT-001-RCP',1,0.4923,13,24.00,240,'[\"Mix flour, sugar, salt, and yeast in a large bowl\",\"Add cold butter pieces and work into the dough\",\"Knead until smooth and elastic\",\"Rest dough in refrigerator for 2 hours\",\"Roll out and fold dough multiple times (lamination)\",\"Cut into triangles and roll into croissant shape\",\"Proof for 1-2 hours until doubled\",\"Brush with egg wash\",\"Bake at 200\\u00b0C for 15-18 minutes until golden\"]','active','02c5d246-e13d-37cf-8292-c501b5a9b7b4','App\\Models\\Employee','2026-01-22 00:35:50','2026-01-22 00:35:50',NULL,100.00),
